-- Create the tenant_admin role
CREATE ROLE tenant_admin;

-- Grant tenant_admin role to the tenant
GRANT tenant_admin TO tenant_data_owner;

-- Enable Row Level Security
ALTER TABLE tenant_data ENABLE ROW LEVEL SECURITY;

-- Create a security policy function
CREATE OR REPLACE FUNCTION tenant_data_tenant_filter()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.tenant_id = current_setting('app.current_tenant_id') THEN
        RETURN NEW;
    ELSE
        RETURN NULL;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create a security policy
CREATE POLICY tenant_data_tenant_filter_policy ON tenant_data
FOR SELECT
USING tenant_data_tenant_filter();

-- Create a security policy for INSERT
CREATE POLICY tenant_data_tenant_filter_insert_policy ON tenant_data
FOR INSERT
USING tenant_data_tenant_filter();

-- Create a security policy for UPDATE
CREATE POLICY tenant_data_tenant_filter_update_policy ON tenant_data
FOR UPDATE
USING tenant_data_tenant_filter();

-- Create a security policy for DELETE
CREATE POLICY tenant_data_tenant_filter_delete_policy ON tenant_data
FOR DELETE
USING tenant_data_tenant_filter();
