-- Create the patients table
CREATE TABLE patients (
    patient_id INT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    ssn VARCHAR(11) NOT NULL,
    medical_history TEXT,
    billing_amount DECIMAL(10, 2)
);

-- Create roles
CREATE ROLE doctor;
CREATE ROLE nurse;
CREATE ROLE billing_clerk;

-- Grant permissions to roles
GRANT SELECT, INSERT, UPDATE, DELETE ON patients TO doctor;
GRANT SELECT, INSERT, UPDATE ON patients TO nurse;
GRANT SELECT ON patients TO billing_clerk;

-- Audit logging table
CREATE TABLE audit_log (
    log_id INT PRIMARY KEY,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    user_role VARCHAR(50),
    table_name VARCHAR(50),
    operation VARCHAR(10),
    patient_id INT,
    data_accessed TEXT
);

-- Function to log SELECT operations on sensitive columns
CREATE OR REPLACE FUNCTION log_select_operation(p_user_role VARCHAR(50), p_table_name VARCHAR(50), p_patient_id INT, p_data_accessed TEXT)
RETURNS VOID AS $$
BEGIN
    INSERT INTO audit_log (user_role, table_name, operation, patient_id, data_accessed)
    VALUES (p_user_role, p_table_name, 'SELECT', p_patient_id, p_data_accessed);
END;
$$ LANGUAGE plpgsql;

-- Trigger to automatically log SELECT operations on sensitive columns
CREATE TRIGGER patient_select_audit
AFTER SELECT ON patients
FOR EACH ROW
EXECUTE FUNCTION log_select_operation(session_user, 'patients', patient_id, details);
```
